{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Halofantrine, the closest structural analogue sharing the dibutylamino alcohol side chain and multiple aryl chlorides, showed low oral bioavailability in patients: peak plasma concentrations after an 8-fold higher oral dose were similar to those after IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A retrospective absolute-bioavailability estimate for halofantrine in fasted humans was approximately 30%, which is above the 20% threshold and represents the main contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol, a highly lipophilic oral drug, had absolute oral bioavailability of approximately 2% in patients, demonstrating that high lipophilicity alone does not ensure adequate oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Prochlorperazine, a lipophilic basic drug with a chlorinated aromatic system, had absolute oral bioavailability of 12.5 ± 4.3%, below the 20% threshold, supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat, a lipophilic oral drug with an ionizable amine, had an absolute oral bioavailability of 0.086 in PBPK simulations, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bambuterol, a lipophilic prodrug, had oral bioavailability of about 10% in healthy adults, below the 20% threshold, reinforcing that lipophilic molecules can still have low oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the closest structural analogue halofantrine and multiple lipophilic/basic oral drugs show low F, and the query's extreme lipophilicity and poor solubility are additional barriers; the single ~30% halofantrine estimate is outweighed by consistent low-F evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The closest analogue, halofantrine, has conflicting estimates (low/erratic vs ~30% fasted), creating threshold uncertainty.",
    "Solubility and first-pass metabolism of the query are not experimentally characterized.",
    "No human PK data exist for the exact ring system and exocyclic double bond of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

